{
  "lecture": [
    {
      "etiquette": "F06",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle (D2 sur les retenues) augmente d'au moins 25 %, sans hausse des fausses découvertes."
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (composantes plantées couvertes dans les propositions brutes et dans les retenues, fausses promotions)"
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucune modification de l'archive servie (aucun masquage)."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "effectuer 6 appels parallèles et indépendants en sessions neuves sans historique par proposeur et par génération, la consigne de chaque appel demandant exactement 1 carte."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dizaines de dollars d'appels pour comparer la couverture oracle de 6 appels d'une carte contre 1 appel de 6 cartes à coût égal."
      },
      "R7": {
        "valeur": 1,
        "passage": "Exploite la propriété de réinitialisation de contexte pour éviter l'effondrement sur un bassin d'idées unique lors de la génération autorégressive séquentielle de plusieurs cartes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F07",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies de profondeur 2 couvertes au sens de l'oracle dans les retenues augmente d'au moins 30 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre total de composantes plantées vraies couvertes dans les retenues, en particulier les composantes conditionnelles de profondeur 2, et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 0,
        "motif": "La poursuite des appels et l'ouverture de générations supplémentaires dépendent des retenues du juge, utilisant ainsi son verdict pour sélectionner les interventions des proposeurs sans traiter cette objection."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "ordonner les P proposeurs du moins cher au plus cher par carte ; appeler d'abord la première moitié (les P/2 proposeurs les moins chers)"
      },
      "R6": {
        "valeur": 1,
        "passage": "L'expérience décisive la moins chère qui la tuerait se réalise sur processeur seul (zéro dépense nouvelle)"
      },
      "R7": {
        "valeur": 0,
        "motif": "Le mécanisme suppose un contrôle strict des fausses découvertes rendant la croissance de l'archive fiable, alors que les faits précisent que la garantie du juge ne borne pas les fausses découvertes au sens de l'oracle."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F08",
      "R1": {
        "valeur": 1,
        "passage": "Les copies par morceaux promues au sens de l'oracle passent du niveau du témoin à au plus 5 % de ce niveau."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : copies promues, composantes vraies couvertes, composantes conditionnelles absorbées. Coût : heures de processeur du juge, la classe étant plus grande."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le dénominateur est le maximum de vraisemblance sur la classe élargie. Le reste du juge est inchangé. La preuve de validité est scellée avant toute course."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche affirme que la garantie se conserve mais ne nomme ni la borne d'espérance des valeurs e, ni le contrôle des comparaisons multiples, ni une garantie équivalente."
      },
      "R5": {
        "valeur": 1,
        "passage": "La classe du nul reçoit, pour chaque paire de lois prises parmi l'archive et les lois aveugles, chaque trait public et chaque décile public, la loi par morceaux de profondeur 1."
      },
      "R6": {
        "valeur": 1,
        "passage": "Quelques heures de processeur. Aucun appel de modèle."
      },
      "R7": {
        "valeur": 1,
        "passage": "Le mécanisme répond à la limite connue du juge, qui cède hors de la classe de son nul : la garde contre les copies est fermée à l'endroit exact où une pression vers la variété fait passer des copies."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F09",
      "R1": {
        "valeur": 1,
        "passage": "à coût égal, au moins 15 % de composantes plantées couvertes en plus à la cinquième génération que la même course sans retour, en moyenne sur les vingt-cinq mondes"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes, lois fausses et copies promues, lues par l'oracle une fois après la course ; dollars et jetons des proposeurs relevés par génération"
      },
      "R3": {
        "valeur": 0,
        "motif": "La consigne des proposeurs reçoit explicitement les valeurs e et les verdicts individuels, sans objection nommée ni justification d'une exception."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "pour chacune de ses six cartes, sa forme canonique, sa valeur e arrondie à deux chiffres et son sort (promue, refusée par e-BH, éliminée au test de mort, refusée par le gardien)"
      },
      "R6": {
        "valeur": 1,
        "passage": "environ 140 USD pour vingt-cinq mondes, deux bras et cinq générations, la consigne allongée d'environ 600 jetons par proposeur et par génération"
      },
      "R7": {
        "valeur": 0,
        "motif": "Apprendre à viser les cartes presque promues ne fournit pas de lien directionnel avec la couverture oracle, puisque les verdicts peuvent aussi orienter vers des copies hors nul ou des écarts de tirage."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F10",
      "R1": {
        "valeur": 1,
        "passage": "à nombre total de tirages frais égal, la part des lois promues qui sont vraies au sens de l'oracle augmente d'au moins 10 points aux générations 5 à 8"
      },
      "R2": {
        "valeur": 1,
        "passage": "lois fausses promues par génération et composantes plantées couvertes, lues par l'oracle après la course ; tirages frais consommés"
      },
      "R3": {
        "valeur": 0,
        "motif": "Calculer les valeurs e sur une statistique adaptativement réutilisée et bruitée ne conserve pas à lui seul leur garantie sous le nul, et fixer m dans e-BH ne rétablit pas cette garantie."
      },
      "R4": {
        "valeur": 0,
        "motif": "La garantie de généralisation invoquée ne précise aucun nul et ne démontre pas la validité des valeurs e calculées à partir des sorties bruitées."
      },
      "R5": {
        "valeur": 0,
        "motif": "La statistique comparée et la transformation de la sortie bruitée en valeur e ne sont pas définies, empêchant de programmer le juge modifié sans clarification."
      },
      "R6": {
        "valeur": 1,
        "passage": "rejouable sur processeur avec des mondes plantés simulés : environ 20 heures de calcul pour trente graines, huit générations et trois bras, aucun appel ni dollar"
      },
      "R7": {
        "valeur": 0,
        "motif": "Limiter le surajustement à une réserve peut améliorer la généralisation, mais n'implique pas une baisse des fausses promotions avec des valeurs e dont la validité après bruitage n'est pas établie."
      },
      "N": {
        "valeur": "C11",
        "passage_fiche": "garder plutôt une réserve fixe de tirages, réutilisée d'une génération à l'autre, sans surajustement",
        "passage_catalogue": "**Réutiliser une réserve de test** de façon adaptative, de nombreuses fois, sans surajustement à la réserve, par un mécanisme qui ne la consulte qu'à travers un seuil bruité."
      }
    }
  ]
}
